'use strict';
const M={};
const C=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step,type:'range'});
const N=(key,label,min,max,value,step=1)=>({...C(key,label,min,max,value,step),type:'number'});
const S=(key,label,options,value)=>({key,label,options,value:value??options[0],type:'select'});
const T=(key,label,value)=>({key,label,value,type:'text'});
const B=(key,label)=>({key,label,type:'button'});
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(4)).toLocaleString('en-US',{maximumFractionDigits:4}):'undefined';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const frac=(a,b)=>`<span class="frac"><span>${esc(a)}</span><span>${esc(b)}</span></span>`;
const svg=(s)=>`<svg viewBox="0 0 600 360" role="img" aria-label="Interactive mathematical model">${s}</svg>`;
const line=(x,y,u,v,color='#4f8073',width=2,dash='')=>`<line x1="${x}" y1="${y}" x2="${u}" y2="${v}" stroke="${color}" stroke-width="${width}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
const rect=(x,y,w,h,color='#89c4ae',stroke='#fff')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}" stroke="${stroke}"/>`;
const dot=(x,y,r=7,color='#287f67')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const txt=(x,y,t,size=18)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}">${esc(t)}</text>`;
const poly=(p,color='#a2d2bb',stroke='#216c58')=>`<polygon points="${p.map(x=>x.join(',')).join(' ')}" fill="${color}" fill-opacity=".65" stroke="${stroke}" stroke-width="2"/>`;
const grid=()=>{let s='';for(let i=-10;i<=10;i++){let p=300+i*25;s+=line(p,20,p,340,'#e2eae6',1);if(i%2===0)s+=txt(p,198,i,12)}for(let i=-6;i<=6;i++)s+=line(50,180-i*25,550,180-i*25,'#e2eae6',1);return s+line(50,180,550,180,'#69877d')+line(300,20,300,340,'#69877d')+txt(555,172,'x',14)+txt(314,22,'y',14)};
const plot=(f,color='#287f67')=>{let seg=[],paths=[];for(let i=0;i<=400;i++){let x=-10+i/20,y=f(x);if(!Number.isFinite(y)||Math.abs(y)>6.5){if(seg.length)paths.push(seg);seg=[]}else seg.push([300+25*x,180-25*y])}if(seg.length)paths.push(seg);return paths.map(p=>`<polyline points="${p.map(x=>x.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="3"/>`).join('')};
const table=(headers,rows)=>`<table class="math-table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);
function model(id,title,controls,prompt,render){M[id]={title,controls,prompt,render}}
model('place','Number builder',[N('n','Number',0,1000000,42),C('digits','Decimal places',0,4,0)],'Build a number. Change one digit. How much does the value change?',s=>{let str=(s.n/10**s.digits).toFixed(s.digits),cols=str.split(''),w=500/cols.length;let pic=cols.map((c,i)=>rect(50+i*w,105,w-5,100,c==='.'?'#fff':i%2?'#e8d9ae':'#b8dacb')+txt(50+i*w+w/2,167,c,36)).join('');let expanded=cols.filter(c=>c!=='.').map((c,i,a)=>`${c} × ${fmt(10**(a.length-i-1-s.digits))}`).join(' + ');return[svg(txt(300,50,'Each place has ten times the value to its right',18)+pic+txt(300,265,str,28)),expanded]});
model('numberline','Number line & operations',[N('a','Start / first number',-1000000,1000000,7,.01),N('b','Second number',-1000000,1000000,5,.01),S('op','Operation',['+','−','×','÷','Compare'])],'Predict the result. How does the direction or distance on the number line support your answer?',s=>{let r=s.op==='+'?s.a+s.b:s.op==='−'?s.a-s.b:s.op==='×'?s.a*s.b:s.op==='÷'?(s.b===0?NaN:s.a/s.b):s.b;let lo=Math.min(0,s.a,Number.isFinite(r)?r:0),hi=Math.max(1,s.a,Number.isFinite(r)?r:1),span=hi-lo,px=n=>50+500*(n-lo)/span;let p=line(50,210,550,210);for(let i=0;i<=10;i++){let x=50+i*50;p+=line(x,202,x,218)+txt(x,245,fmt(lo+span*i/10),12)}p+=dot(px(s.a),210,9)+txt(px(s.a),185,'A: '+fmt(s.a),15);if(Number.isFinite(r))p+=line(px(s.a),130,px(r),130,'#c38c35',4)+dot(px(r),210,9,'#c38c35')+txt(px(r),95,(s.op==='Compare'?'B: ':'Result: ')+fmt(r),20);return[svg(p),s.op==='Compare'?`${fmt(s.a)} ${s.a<s.b?'&lt;':s.a>s.b?'&gt;':'='} ${fmt(s.b)}`:`${fmt(s.a)} ${s.op} ${fmt(s.b)} = ${fmt(r)}${s.op==='÷'&&s.b===0?' — division by zero is undefined.':''}`]});
model('ordinal','Ordinal positions',[C('n','Number of objects',2,100,10),C('p','Chosen position',1,100,3)],'Choose an object and count from each end. Why does its ordinal position change?',s=>{let p=Math.min(s.p,s.n),suffix=n=>n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th');return[`<div class="number-tiles">${Array.from({length:s.n},(_,i)=>`<span class="${i+1===p?'highlight':''}">${i+1}${suffix(i+1)}</span>`).join('')}</div>`,`${p}${suffix(p)} from the start; ${s.n-p+1}${suffix(s.n-p+1)} from the end.`]});
model('round','Rounding explorer',[N('n','Number',0,1000000,3674,.0001),S('place','Round to',['100000','1000','100','10','1','0.1','0.01','0.001'])],'Find two numbers that round to the same value. Where is the halfway point?',s=>{let p=+s.place,lo=Math.floor(s.n/p)*p,hi=lo+p,r=Math.round(s.n/p)*p,x=60+480*(s.n-lo)/p;return[svg(line(60,200,540,200)+dot(60,200)+dot(540,200)+line(300,175,300,225,'#c38c35',2,'6 4')+dot(x,200,12)+txt(60,245,fmt(lo))+txt(540,245,fmt(hi))+txt(300,270,'Halfway: '+fmt(lo+p/2),16)+txt(x,145,fmt(s.n),24)),`${fmt(s.n)} rounded to the nearest ${s.place} is <b>${fmt(r)}</b>.`]});
model('arrays','Equal groups & arrays',[C('rows','Groups / rows',1,12,3),C('cols','Objects per group',1,12,7),C('extra','Extra objects',0,11,0)],'Build 24 objects in different rectangular arrays. What multiplication and division facts can you write?',s=>{let p='',dx=Math.min(38,450/s.cols),dy=Math.min(23,270/s.rows);for(let r=0;r<s.rows;r++)for(let c=0;c<s.cols;c++)p+=dot(70+c*dx,50+r*dy,8,r%2?'#d6a550':'#3a9375');for(let i=0;i<s.extra;i++)p+=dot(70+i*32,330,7,'#8f91c4');return[svg(p),`${s.rows} × ${s.cols} = ${s.rows*s.cols}. With ${s.extra} extra: ${s.rows*s.cols+s.extra} ÷ ${s.rows} = ${Math.floor((s.rows*s.cols+s.extra)/s.rows)} remainder ${(s.rows*s.cols+s.extra)%s.rows}.`]});
model('fraction','Fraction studio',[C('a','Numerator A',0,24,3),C('b','Denominator A',1,12,4),C('c','Numerator B',0,24,1),C('d','Denominator B',1,12,2),S('op','Explore',['Compare','Add','Subtract','Multiply','Divide'])],'Make two different fractions that cover the same amount. Explain why their numerators and denominators differ.',s=>{let bars=(n,d,y,color)=>{let str='';let wholes=Math.max(1,Math.ceil(n/d)),unit=480/Math.max(wholes,Math.ceil(s.a/s.b),Math.ceil(s.c/s.d),1);for(let k=0;k<wholes*d;k++)str+=rect(60+k*unit/d,y,unit/d,48,k<n?color:'#f1f4f2','#fff');for(let k=0;k<wholes;k++)str+=`<rect x="${60+k*unit}" y="${y}" width="${unit}" height="48" fill="none" stroke="#476f5c" stroke-width="2"/>`;return str};let A=s.a/s.b,Bv=s.c/s.d,v=s.op==='Add'?A+Bv:s.op==='Subtract'?A-Bv:s.op==='Multiply'?A*Bv:s.op==='Divide'?(Bv?A/Bv:NaN):A;let num,den;if(s.op==='Add'||s.op==='Subtract'){num=s.a*s.d+(s.op==='Add'?1:-1)*s.c*s.b;den=s.b*s.d}else if(s.op==='Multiply'){num=s.a*s.c;den=s.b*s.d}else{num=s.a*s.d;den=s.b*s.c}let d=gcd(num,den)||1;let res=s.op==='Compare'?`${frac(s.a,s.b)} ${A<Bv?'&lt;':A>Bv?'&gt;':'='} ${frac(s.c,s.d)}`:`${frac(s.a,s.b)} ${{Add:'+',Subtract:'−',Multiply:'×',Divide:'÷'}[s.op]} ${frac(s.c,s.d)} = ${Number.isFinite(v)?frac(num/d,den/d)+' ≈ '+fmt(v):'undefined (cannot divide by zero)'}`;return[svg(txt(300,48,'One outlined unit represents one whole',17)+bars(s.a,s.b,100,'#63ad91')+txt(300,185,`${s.a} parts of size 1/${s.b}`,18)+bars(s.c,s.d,230,'#d6ab60')+txt(300,315,`${s.c} parts of size 1/${s.d}`,18)),res]});
model('percent','Fraction • decimal • percent',[C('n','Shaded squares',0,100,35),N('base','Whole quantity',1,100000,200)],'Shade the same amount as one quarter. How can you express it as a fraction, decimal, and percentage?',s=>{let p='';for(let i=0;i<100;i++)p+=rect(150+i%10*28,20+Math.floor(i/10)*28,26,26,i<s.n?'#438e74':'#e7eee9');return[svg(p+txt(300,335,s.n+' out of 100',21)),`${frac(s.n,100)} = ${fmt(s.n/100)} = ${s.n}%. ${s.n}% of ${fmt(s.base)} = <b>${fmt(s.n*s.base/100)}</b>.`]});
model('ratio','Ratio & proportion',[C('a','First part',1,12,2),C('b','Second part',1,12,3),C('k','Scale factor',1,10,2)],'Keep the mixture the same while doubling its size. Which numbers change, and which relationship stays constant?',s=>{let p='';for(let i=0;i<s.a;i++)p+=dot(65+i*39,95,13,'#399777');for(let i=0;i<s.b;i++)p+=dot(65+i*39,165,13,'#d5a24e');p+=txt(300,240,`${s.a} : ${s.b} = ${s.a*s.k} : ${s.b*s.k}`,30);return[svg(p),`Part–whole: ${frac(s.a,s.a+s.b)}. Scale both parts by ${s.k}: ${s.a*s.k} + ${s.b*s.k} = ${(s.a+s.b)*s.k}.`]});
model('factors','Factors & prime numbers',[C('n','First number',1,100,24),C('m','Second number',1,100,36),S('view','Highlight',['Factors','Multiples','Primes'])],'Find a pair of numbers whose GCF is 6. How do common factors differ from common multiples?',s=>{let factors=n=>Array.from({length:n},(_,i)=>i+1).filter(i=>n%i===0),f=factors(s.n),g=gcd(s.n,s.m);return[`<div class="number-tiles">${Array.from({length:100},(_,i)=>{let n=i+1,hit=s.view==='Factors'?s.n%n===0:s.view==='Multiples'?n%s.n===0:n>1&&factors(n).length===2;return`<span class="${hit?'highlight':''}">${n}</span>`}).join('')}</div>`,`Factors of ${s.n}: ${f.join(', ')}. ${s.n===1?'1 is neither prime nor composite.':f.length===2?'Prime: exactly two factors.':'Composite: more than two factors.'}<br>GCF(${s.n}, ${s.m}) = ${g}; LCM = ${s.n*s.m/g}.`]});
model('pattern','Pattern machine',[N('start','Starting number',-100,100,2),N('step','Difference / multiplier',-10,10,3),S('type','Rule',['Add','Multiply','Repeat'])],'Predict the next three terms. Can you explain the rule and invent a different pattern?',s=>{let a=Array.from({length:8},(_,i)=>s.type==='Add'?s.start+i*s.step:s.type==='Multiply'?s.start*s.step**i:[s.start,s.step,s.start+s.step][i%3]);return[svg(a.map((x,i)=>rect(45+i%4*135,75+Math.floor(i/4)*110,120,75,i%2?'#efdcba':'#b6dbc9')+txt(105+i%4*135,123+Math.floor(i/4)*110,fmt(x),21)).join('')),s.type==='Add'?`Term n = ${s.start} + (n − 1) × ${s.step}`:s.type==='Multiply'?`Term n = ${s.start} × (${s.step})ⁿ⁻¹`:`Repeating unit: ${a.slice(0,3).join(', ')}`]});
model('money','Peso money lab',[C('ones','₱1 coins',0,20,5),C('fives','₱5 coins',0,20,2),C('tens','₱10 coins',0,20,3),C('twenties','₱20',0,20,1),C('hundreds','₱100 bills',0,100,0),N('cost','Purchase cost (₱)',0,10000,35,.25)],'Make the same amount in two different ways. Predict the change before changing the purchase cost.',s=>{let total=s.ones+s.fives*5+s.tens*10+s.twenties*20+s.hundreds*100;return[svg([['₱1',s.ones],['₱5',s.fives],['₱10',s.tens],['₱20',s.twenties],['₱100',s.hundreds]].map(([v,n],i)=>dot(80+i*110,130,42,i%2?'#d4b673':'#b8cdbe')+txt(80+i*110,135,v,21)+txt(80+i*110,210,'× '+n,22)).join('')+txt(300,300,'Illustrative tokens, not banknote reproductions',13)),`Total: ₱${fmt(total)}. Cost: ₱${fmt(s.cost)}. ${total>=s.cost?'Change: ₱'+fmt(total-s.cost):'Need ₱'+fmt(s.cost-total)+' more.'}`]});
model('clock','Time & time zones',[C('hour','Hour (24-hour)',0,23,15),C('minute','Minute',0,59,0),C('elapsed','Minutes later',0,720,90),C('zone','Destination UTC offset',-12,14,8)],'Set 3:45 p.m. Predict the time 90 minutes later. How is it written in the 24-hour system?',s=>{let p='<circle cx="300" cy="170" r="130" fill="#f4f6ef" stroke="#8cad9e" stroke-width="3"/>';for(let i=1;i<=12;i++){let a=i*Math.PI/6;p+=txt(300+105*Math.sin(a),177-105*Math.cos(a),i,19)}let h=(s.hour%12+s.minute/60)*Math.PI/6,m=s.minute*Math.PI/30;p+=line(300,170,300+70*Math.sin(h),170-70*Math.cos(h),'#245e50',7)+line(300,170,300+100*Math.sin(m),170-100*Math.cos(m),'#c39345',4)+dot(300,170);let total=s.hour*60+s.minute+s.elapsed,world=s.hour*60+s.minute+(s.zone-8)*60;let clock=n=>`${String(Math.floor(((n%1440)+1440)%1440/60)).padStart(2,'0')}:${String(((n%60)+60)%60).padStart(2,'0')}`;return[svg(p),`${s.hour%12||12}:${String(s.minute).padStart(2,'0')} ${s.hour<12?'a.m.':'p.m.'} = ${clock(s.hour*60+s.minute)}. After ${s.elapsed} min: ${clock(total)}${total>=1440?' (next day)':''}.<br>Philippines UTC+8 → UTC${s.zone>=0?'+':''}${s.zone}: ${clock(world)} (${world<0?'previous':world>=1440?'next':'same'} day). Fixed UTC offsets; daylight-saving changes are not applied.`]});
model('calendar','Calendar explorer',[N('year','Year',2000,2100,2026),C('month','Month',1,12,11),C('day','Day',1,31,20),C('later','Days later',0,60,7)],'Choose a date. What date will it be two weeks later? Explain how you counted across the end of a month.',s=>{let days=new Date(Date.UTC(s.year,s.month,0)).getUTCDate(),day=Math.min(s.day,days),d=new Date(Date.UTC(s.year,s.month-1,day)),end=new Date(d.getTime()+s.later*86400000),start=new Date(Date.UTC(s.year,s.month-1,1)).getUTCDay(),cells=Array.from({length:42},(_,i)=>i-start+1);let rows=[];for(let j=0;j<6;j++)rows.push(cells.slice(j*7,j*7+7).map(x=>x>0&&x<=days?(x===day?'['+x+']':x):''));return[`<div class="canvas-column"><h3>${d.toLocaleString('en',{month:'long',year:'numeric',timeZone:'UTC'})}</h3>${table(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],rows)}</div>`,`${d.toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'})} + ${s.later} days = ${end.toLocaleDateString('en',{weekday:'long',year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})}.`]});
model('units','Measure & convert',[N('n','Measurement',0,100000,3.5,.001),S('unit','Conversion',['m → cm','km → m','kg → g','g → mg','L → mL','cm³ → L','m² → cm²','hours → minutes','minutes → seconds','inches → cm']),S('direction','Direction',['Forward','Reverse'])],'Predict what happens to the number when you express a measurement in a smaller unit. Test three examples.',s=>{let k={'m → cm':100,'km → m':1000,'kg → g':1000,'g → mg':1000,'L → mL':1000,'cm³ → L':.001,'m² → cm²':10000,'hours → minutes':60,'minutes → seconds':60,'inches → cm':2.54}[s.unit];let parts=s.unit.split(' → ');if(s.direction==='Reverse'){parts.reverse();k=1/k}let p=line(60,210,540,210);for(let i=0;i<=10;i++)p+=line(60+i*48,190,60+i*48,220)+txt(60+i*48,250,fmt(s.n*i/10),12);return[svg(txt(300,90,`${fmt(s.n)} ${parts[0]}`,32)+p+txt(300,320,`${fmt(s.n*k)} ${parts[1]}`,25)),`Multiply by ${fmt(k)}: ${fmt(s.n)} ${parts[0]} = ${fmt(s.n*k)} ${parts[1]}.`]});
model('length','Length & distance',[C('length','Object length',1,20,12),C('unit','Length of one measuring unit',1,5,2)],'Measure the same object with two different unit sizes. Why does the number of units change?',s=>{let p=rect(60,80,s.length*23,55,'#d9b263');for(let i=0;i<s.length/s.unit;i++)p+=rect(60+i*s.unit*23,175,Math.min(s.unit,s.length-i*s.unit)*23,35,i%2?'#4e9a7c':'#b7d9c6');return[svg(p+txt(300,270,'Same length, different-sized units',20)),`Length = ${s.length} small units = ${fmt(s.length/s.unit)} measuring units of size ${s.unit}.`]});
model('shapes','Shape & area studio',[S('shape','Shape',['Rectangle','Square','Triangle','Parallelogram','Trapezoid','Circle','Kite']),C('w','Width / base / diameter',1,12,6),C('h','Height / second diagonal',1,10,4),C('top','Top base (trapezoid)',1,10,3)],'Keep the height fixed and double the base. What happens to the area? Explain using the model.',s=>{let w=s.w*30,h=(s.shape==='Square'?s.w:s.h)*25,x=100,y=300-h,p='',a=s.w*s.h,per=2*(s.w+s.h),desc='A = base × height',points;if(s.shape==='Rectangle'||s.shape==='Square'){h=(s.shape==='Square'?s.w:s.h)*25;a=s.w*(s.shape==='Square'?s.w:s.h);per=2*(s.w+(s.shape==='Square'?s.w:s.h));p=rect(x,300-h,w,h);for(let i=1;i<s.w;i++)p+=line(x+i*30,300-h,x+i*30,300,'#fff',1);for(let i=1;i<(s.shape==='Square'?s.w:s.h);i++)p+=line(x,300-i*25,x+w,300-i*25,'#fff',1)}else if(s.shape==='Circle'){let r=s.w/2;p=`<circle cx="300" cy="180" r="${s.w*12}" fill="#9ccbb4" stroke="#38785e"/>`+line(300,180,300+s.w*12,180)+txt(300,50,'r = '+fmt(r));a=Math.PI*r*r;per=Math.PI*s.w;desc='A = πr²; C = 2πr'}else{points=s.shape==='Triangle'?[[x,300],[x+w,300],[x,300-h]]:s.shape==='Parallelogram'?[[x,300],[x+w,300],[x+w+45,300-h],[x+45,300-h]]:s.shape==='Trapezoid'?[[x,300],[x+w,300],[x+s.top*30,300-h],[x,300-h]]:[[300,300],[300-w/2,300-h/2],[300,300-h],[300+w/2,300-h/2]];p=poly(points);if(['Triangle','Kite'].includes(s.shape)){a=s.w*s.h/2;desc=s.shape==='Kite'?'A = ½d₁d₂':'A = ½bh'}if(s.shape==='Trapezoid'){a=(s.w+s.top)*s.h/2;desc='A = ½(b₁ + b₂)h'}per=null;p+=line(x,300,x,300-h,'#bf8e40',3,'5 5')}return[svg(p+txt(300,335,'Lengths are in units; areas are in square units.',14)),`${desc}. Area = <b>${fmt(a)} square units</b>.${per!==null?' '+(s.shape==='Circle'?'Circumference':'Perimeter')+' = '+fmt(per)+' units.':''}`]});
model('angle','Angle & line explorer',[C('a','Angle in degrees',0,180,60),S('view','View',['Angle','Parallel lines & transversal'])],'Make an acute, a right, and an obtuse angle. What happens to the supplementary angle as your angle grows?',s=>{let a=s.a*Math.PI/180,p='';if(s.view==='Angle'){p=line(180,270,480,270,'#31816a',4)+line(180,270,180+260*Math.cos(a),270-260*Math.sin(a),'#c49343',4);for(let i=0;i<=180;i+=10){let r=i*Math.PI/180;p+=line(180+115*Math.cos(r),270-115*Math.sin(r),180+125*Math.cos(r),270-125*Math.sin(r),'#789c8e',1)}p+=txt(300,45,s.a+'°',32)}else{p=line(60,100,540,100,'#31816a',4)+line(60,260,540,260,'#31816a',4);let dx=Math.cos(a)*180,dy=Math.sin(a)*180;p+=line(300-dx,180+dy,300+dx,180-dy,'#c49343',4)+txt(440,80,s.a+'°')+txt(440,240,s.a+'°')}let type=s.a===0?'zero':s.a<90?'acute':s.a===90?'right':s.a<180?'obtuse':'straight';return[svg(p),`${s.a}° is a ${type} angle. Supplementary angle: ${180-s.a}°. ${s.a<=90?'Complementary angle: '+(90-s.a)+'°.':''}${s.view!=='Angle'?' Equal corresponding angles require parallel lines; 0° and 180° are degenerate transversal cases.':''}`]});
model('transform','Transformations & symmetry',[C('x','Horizontal translation',-6,6,2),C('y','Vertical translation',-5,5,1),S('reflect','Reflection',['None','x-axis','y-axis']),S('rotate','Rotation counterclockwise',['0','90','180','270'])],'Predict where each vertex will move after a quarter turn. Which properties of the triangle stay the same?',s=>{let pts=[[1,1],[4,1],[2,4]],rad=+s.rotate*Math.PI/180,moved=pts.map(([x,y])=>{if(s.reflect==='x-axis')y=-y;if(s.reflect==='y-axis')x=-x;return[x*Math.cos(rad)-y*Math.sin(rad)+s.x,x*Math.sin(rad)+y*Math.cos(rad)+s.y]});let draw=p=>p.map(([x,y])=>[300+x*25,180-y*25]);return[svg(grid()+poly(draw(pts),'#b9d8c9','#81a598')+poly(draw(moved),'#e8be71','#b78532')),`Reflect, then rotate ${s.rotate}°, then translate (${s.x}, ${s.y}). New vertices: ${moved.map(p=>'('+p.map(fmt).join(', ')+')').join('; ')}. Lengths and angles are preserved. Some vertices may lie outside this viewing window.`]});
model('tessellation','Tessellation builder',[S('shape','Tile shape',['Square','Rectangle','Triangle','Hexagon']),C('size','Tile size',20,70,40)],'Which shapes cover the surface without gaps or overlaps? Explain how angles meet at a vertex.',s=>{let p='',z=s.size;if(s.shape==='Hexagon'){let r=z/1.7;for(let i=0;i<12;i++)for(let j=0;j<8;j++){let cx=30+i*r*1.5,cy=30+j*r*Math.sqrt(3)+(i%2)*r*Math.sqrt(3)/2;p+=poly(Array.from({length:6},(_,k)=>[cx+r*Math.cos(k*Math.PI/3),cy+r*Math.sin(k*Math.PI/3)]),(i+j)%2?'#dbc18c':'#83baa1','#fff')}}else for(let x=10;x<580;x+=z)for(let y=10;y<340;y+=s.shape==='Rectangle'?z/2:z){let h=s.shape==='Rectangle'?z/2:z;p+=rect(x,y,z,h,(Math.round(x/z)+Math.round(y/h))%2?'#b3d6c0':'#e6c791');if(s.shape==='Triangle')p+=poly([[x,y],[x+z,y],[x+z,y+h]],'#69a38a','#fff')}return[svg(p),`${s.shape} tiles repeat by translation${s.shape==='Triangle'?' and half-turns':''}. Interior angles around a fully covered vertex total 360°.`]});
model('solid','Solids, volume & surface area',[S('shape','Solid',['Rectangular prism','Cube','Cylinder','Cone','Sphere','Square pyramid']),C('a','Length / radius / base side',1,10,4),C('b','Width',1,10,3),C('h','Height',1,10,6)],'Double one dimension. Predict the effect on volume. Compare a cone and cylinder with the same radius and height.',s=>{let a=s.a,b=s.shape==='Cube'?a:s.b,h=s.shape==='Cube'?a:s.h,V=a*b*h,SA=2*(a*b+a*h+b*h),p='',desc='V = lwh';if(s.shape.includes('prism')||s.shape==='Cube'){let x=180,y=270,w=a*25,ht=h*20,depth=b*10;p=poly([[x,y],[x+w,y],[x+w,y-ht],[x,y-ht]])+poly([[x,y-ht],[x+depth,y-ht-depth],[x+w+depth,y-ht-depth],[x+w,y-ht]],'#debd7e')+poly([[x+w,y],[x+w+depth,y-depth],[x+w+depth,y-ht-depth],[x+w,y-ht]],'#6b9c83')}else if(s.shape==='Sphere'){V=4/3*Math.PI*a**3;SA=4*Math.PI*a*a;desc='V = ⁴⁄₃πr³';p=`<circle cx="300" cy="180" r="${a*13}" fill="#9fcab2" stroke="#4f876d"/><ellipse cx="300" cy="180" rx="${a*13}" ry="${a*4}" fill="none" stroke="#4f876d"/>`}else if(s.shape==='Square pyramid'){V=a*a*h/3;SA=a*a+2*a*Math.hypot(h,a/2);desc='V = ⅓b²h';p=poly([[170,280],[350,310],[440,250],[300,50]],'#a2cdb7')+line(300,50,350,310)}else{V=Math.PI*a*a*h*(s.shape==='Cone'?1/3:1);SA=s.shape==='Cone'?Math.PI*a*(a+Math.hypot(a,h)):2*Math.PI*a*(a+h);desc=s.shape==='Cone'?'V = ⅓πr²h':'V = πr²h';let rx=a*15,ht=h*22;p=s.shape==='Cone'?poly([[300-rx,290],[300+rx,290],[300,290-ht]]):rect(300-rx,290-ht,rx*2,ht);p+=`<ellipse cx="300" cy="290" rx="${rx}" ry="22" fill="#6fa78d" stroke="#467f65"/>`;if(s.shape==='Cylinder')p+=`<ellipse cx="300" cy="${290-ht}" rx="${rx}" ry="22" fill="#c2ddcc" stroke="#467f65"/>`}return[svg(p+txt(300,340,s.shape+' (schematic)',16)),`${desc}. Volume ≈ ${fmt(V)} cubic units. Total surface area ≈ ${fmt(SA)} square units.`]});
model('nets','Cube net',[C('size','Side length',1,10,3)],'Imagine folding the net. Which faces will be opposite? How does doubling the side change total surface area?',s=>{let p='',z=60;[[1,0],[0,1],[1,1],[2,1],[3,1],[1,2]].forEach(([x,y],i)=>p+=rect(150+x*z,70+y*z,z,z,['#c6dfd0','#e2c38a','#8bbca3','#b6d5c2','#d9c8a2','#75a48c'][i])+txt(180+x*z,107+y*z,String.fromCharCode(65+i),20));return[svg(p),`6 equal square faces; 12 edges; 8 vertices. Surface area = 6 × ${s.size}² = ${6*s.size*s.size} square units. Volume = ${s.size**3} cubic units.`]});
model('circle','Circle geometry',[C('r','Radius',1,10,4),C('angle','Central angle',1,359,90)],'Keep the radius fixed and double the central angle. What happens to the sector area and arc length?',s=>{let r=120,a=s.angle*Math.PI/180,x=300+r*Math.cos(a),y=180-r*Math.sin(a),p=`<circle cx="300" cy="180" r="120" fill="#f1f6f2" stroke="#558e73"/><path d="M300 180 L420 180 A120 120 0 ${s.angle>180?1:0} 0 ${x} ${y} Z" fill="#a4ceb7" stroke="#377e5d"/>`+line(420,180,x,y,'#bb8d41',3)+dot(300,180)+txt(300,335,'Radius '+s.r+' units',18);let area=Math.PI*s.r*s.r,sector=area*s.angle/360,segment=sector-.5*s.r*s.r*Math.sin(a);return[svg(p),`Circumference ≈ ${fmt(2*Math.PI*s.r)}; area ≈ ${fmt(area)}.<br>Arc ≈ ${fmt(2*Math.PI*s.r*s.angle/360)}; sector ≈ ${fmt(sector)}; corresponding segment ≈ ${fmt(segment)} square units. An inscribed angle subtending this arc has measure ${fmt(s.angle/2)}° (vertex on the complementary arc).`]});
model('triangle','Triangle & trigonometry',[C('a','Side a',1,15,5),C('b','Side b',1,15,7),C('C','Included angle C',1,179,60)],'Keep two sides fixed and increase the included angle. What happens to the opposite side? Verify with the cosine rule.',s=>{let rad=s.C*Math.PI/180,c=Math.sqrt(s.a*s.a+s.b*s.b-2*s.a*s.b*Math.cos(rad)),A=Math.acos(Math.max(-1,Math.min(1,(s.b*s.b+c*c-s.a*s.a)/(2*s.b*c))))*180/Math.PI,Bv=180-s.C-A;let p=poly([[90,290],[90+s.b*27,290],[90+s.a*27*Math.cos(rad),290-s.a*27*Math.sin(rad)]])+txt(300,45,'c² = a² + b² − 2ab cos C',22);return[svg(p),`c ≈ ${fmt(c)}. A ≈ ${fmt(A)}°; B ≈ ${fmt(Bv)}°. Area = ½ab sin C ≈ ${fmt(.5*s.a*s.b*Math.sin(rad))}.<br>a / sin A = b / sin B = c / sin C ≈ ${fmt(c/Math.sin(rad))}.`]});
model('sine','Sine rule: ambiguous case',[C('A','Known angle A',1,170,30),C('a','Opposite side a',1,15,6),C('b','Other side b',1,15,10)],'Use A = 30°, a = 6, b = 10. Why can two triangles fit the same three measurements?',s=>{let v=s.b*Math.sin(s.A*Math.PI/180)/s.a,sol=[];if(v<=1+1e-12){let B1=Math.asin(Math.abs(v-1)<1e-12?1:v)*180/Math.PI;[B1,180-B1].forEach(Bv=>{let C=180-s.A-Bv;if(C>0&&!sol.some(x=>Math.abs(x.B-Bv)<1e-5))sol.push({B:Bv,C,c:s.a*Math.sin(C*Math.PI/180)/Math.sin(s.A*Math.PI/180)})})}let p=txt(300,45,'sin B = b sin A / a = '+fmt(v),22);sol.forEach((x,i)=>{let z=12,xx=80+i*280;p+=poly([[xx,280],[xx+x.c*z,280],[xx+s.b*z*Math.cos(s.A*Math.PI/180),280-s.b*z*Math.sin(s.A*Math.PI/180)]],i?'#e4c385':'#8ebfa5')+txt(xx+100,325,'Solution '+(i+1),18)});return[svg(p),sol.length?sol.map((x,i)=>`Triangle ${i+1}: B ≈ ${fmt(x.B)}°, C ≈ ${fmt(x.C)}°, c ≈ ${fmt(x.c)}.`).join('<br>'):'No triangle: the measurements are incompatible.']});
model('right','Right triangle explorer',[C('a','Horizontal leg',1,12,4),C('b','Vertical leg',1,10,3),C('k','Similarity scale',1,3,1,.1)],'Build a 3–4–5 triangle. Scale both legs by the same factor. Which ratios stay unchanged?',s=>{let h=Math.hypot(s.a,s.b),theta=Math.atan2(s.b,s.a),p=poly([[100,300],[100+s.a*32,300],[100+s.a*32,300-s.b*25]])+txt(300,60,'a² + b² = c²',27)+txt(300,340,'Horizontal '+s.a+' • vertical '+s.b,17);return[svg(p),`Hypotenuse = √(${s.a}² + ${s.b}²) ≈ ${fmt(h)}. Angle of elevation ≈ ${fmt(theta*180/Math.PI)}°.<br>sin θ = ${fmt(s.b/h)}; cos θ = ${fmt(s.a/h)}; tan θ = ${fmt(s.b/s.a)}. Scaled sides: ${fmt(s.a*s.k)}, ${fmt(s.b*s.k)}, ${fmt(h*s.k)}.`]});
model('coordinates','Coordinate explorer',[C('x','Point A: x',-9,9,-3),C('y','Point A: y',-5,5,2),C('u','Point B: x',-9,9,4),C('v','Point B: y',-5,5,-2)],'Move the points so their midpoint is the origin. How are their coordinates related?',s=>{let p=grid()+line(300+s.x*25,180-s.y*25,300+s.u*25,180-s.v*25,'#c39749',3)+dot(300+s.x*25,180-s.y*25)+dot(300+s.u*25,180-s.v*25)+dot(300+(s.x+s.u)*12.5,180-(s.y+s.v)*12.5,7,'#bd8838');return[svg(p),`A(${s.x}, ${s.y}), B(${s.u}, ${s.v}). Midpoint (${fmt((s.x+s.u)/2)}, ${fmt((s.y+s.v)/2)}). Distance √(Δx²+Δy²) ≈ ${fmt(Math.hypot(s.u-s.x,s.v-s.y))}.`]});
model('linear','Linear graphs & systems',[C('m','Slope m',-4,4,1,.25),C('b','Intercept b',-5,5,1,.5),C('n','Second slope',-4,4,-1,.25),C('c','Second intercept',-5,5,3,.5),S('view','View',['One line','Two lines','y ≥ mx + b'])],'Make two lines with one intersection, then no intersections. What needs to change for infinitely many solutions?',s=>{let p=grid();if(s.view==='y ≥ mx + b'){for(let x=-10;x<10;x+=.1){let y=Math.max(-6,Math.min(6,s.m*x+s.b));p+=rect(300+x*25,30,2.5,150-y*25,'#cce4d5','none')}}p+=plot(x=>s.m*x+s.b);let r=`y = ${s.m}x + (${s.b}). Slope = ${s.m}; y-intercept = ${s.b}; ${s.m?'x-intercept = '+fmt(-s.b/s.m):s.b===0?'every point on the line is an x-intercept':'no x-intercept'}.`;if(s.view==='Two lines'){p+=plot(x=>s.n*x+s.c,'#c38b35');r+=s.m===s.n?(s.b===s.c?' Coincident lines: infinitely many solutions.':' Parallel lines: no solution.'):` Intersection: (${fmt((s.c-s.b)/(s.m-s.n))}, ${fmt(s.m*(s.c-s.b)/(s.m-s.n)+s.b)}).`}if(s.view.startsWith('y ≥'))r+=' Shading shows solutions on or above the solid boundary.';return[svg(p),r]});
model('quadratic','Quadratic graph lab',[C('a','Coefficient a',-3,3,1,.25),C('h','Vertex h',-5,5,0,.5),C('k','Vertex k',-5,5,-2,.5),S('shade','View',['Curve','y ≥ f(x)','y ≤ f(x)'])],'Move the vertex without changing the shape. Then change a. How do direction and width respond?',s=>{let f=x=>s.a*(x-s.h)**2+s.k,p=grid();if(s.shade!=='Curve')for(let x=-10;x<10;x+=.08){let y=Math.max(-6,Math.min(6,f(x))),sy=180-y*25;p+=rect(300+x*25,s.shade==='y ≥ f(x)'?30:sy,2, s.shade==='y ≥ f(x)'?sy-30:330-sy,'#d3e7d8','none')}p+=plot(f);let b=-2*s.a*s.h,c=s.a*s.h*s.h+s.k,D=b*b-4*s.a*c;let roots=s.a===0?'Degenerate: a = 0 gives a constant function.':-s.k/s.a<0?'No real zeros.':`Zeros: ${fmt(s.h-Math.sqrt(-s.k/s.a))}, ${fmt(s.h+Math.sqrt(-s.k/s.a))}.`;return[svg(p),`y = ${s.a}(x − (${s.h}))² + (${s.k}) = ${s.a}x² + (${fmt(b)})x + (${fmt(c)}).<br>${s.a?'Vertex ('+s.h+', '+s.k+'); axis x = '+s.h+'. ':''}${roots} Discriminant = ${fmt(D)}.`]});
model('inequality','Inequality number line',[C('a','Left root / boundary',-8,8,-2),C('b','Right root / boundary',-8,8,3),S('type','Relation',['(x − a)(x − b) ≤ 0','(x − a)(x − b) ≥ 0','|x| ≤ b','|x| ≥ b','x ≤ a','x ≥ a'])],'Compare the solutions inside and outside two roots. Test x = 0 and explain whether it belongs.',s=>{let lo=Math.min(s.a,s.b),hi=Math.max(s.a,s.b),segments=[],answer='';if(s.type.includes('(x')){if(s.type.includes('≤')){segments=[[lo,hi]];answer=`[${lo}, ${hi}]`}else{segments=[[-10,lo],[hi,10]];answer=`(−∞, ${lo}] ∪ [${hi}, ∞)`}}else if(s.type.includes('|')){if(s.b<0){segments=s.type.includes('≥')?[[-10,10]]:[];answer=s.type.includes('≥')?'All real numbers':'No real solutions'}else if(s.type.includes('≤')){segments=[[-s.b,s.b]];answer=`[${-s.b}, ${s.b}]`}else{segments=[[-10,-s.b],[s.b,10]];answer=`(−∞, ${-s.b}] ∪ [${s.b}, ∞)`}}else{segments=s.type.includes('≤')?[[-10,s.a]]:[[s.a,10]];answer=s.type.includes('≤')?`(−∞, ${s.a}]`:`[${s.a}, ∞)`}let p=line(50,190,550,190);for(let i=-10;i<=10;i++)p+=line(300+i*25,180,300+i*25,200)+txt(300+i*25,230,i,12);for(let [a,b]of segments)p+=line(300+a*25,190,300+b*25,190,'#2d9974',8)+dot(300+a*25,190)+dot(300+b*25,190);return[svg(p+txt(300,70,'Highlighted values satisfy the inequality',19)),`a = ${s.a}, b = ${s.b}. Solution: <b>${answer}</b>. Display window: −10 to 10; infinite intervals continue beyond it.`]});
model('balance','Equation balance',[C('a','Coefficient a',1,10,2),C('b','Constant b',-10,20,3),C('c','Right side c',-20,40,15),C('x','Test x',-20,20,6,.5)],'Find x so the balance is level. Explain why subtracting the same number from both sides preserves equality.',s=>{let lhs=s.a*s.x+s.b,delta=Math.max(-40,Math.min(40,(lhs-s.c)*3)),p=line(130,150+delta,470,150-delta,'#4d8570',6)+poly([[270,280],[330,280],[300,155]],'#dcbd7e')+rect(90,165+delta,100,45,'#a6ccb7')+rect(420,165-delta,100,45,'#d7bd85')+txt(140,145+delta,fmt(lhs),22)+txt(470,145-delta,s.c,22);return[svg(p),`${s.a}x + (${s.b}) = ${s.c}. At x = ${s.x}: ${fmt(lhs)} ${lhs===s.c?'=':lhs<s.c?'&lt;':'&gt;'} ${s.c}. Solution x = (c − b) / a = ${fmt((s.c-s.b)/s.a)}.`]});
model('polynomial','Algebra area tiles',[C('x','Value of x',1,8,3),C('a','First constant a',0,8,2),C('b','Second constant b',0,8,4)],'Compare (x + 2)(x + 3) with the four regions. Where does each term in the expansion come from?',s=>{let z=20,x=s.x*z,a=s.a*z,b=s.b*z,p=rect(90,70,x,x,'#6cae8c')+rect(90+x,70,a,x,'#d6b367')+rect(90,70+x,x,b,'#d6b367')+rect(90+x,70+x,a,b,'#b1b5cf')+txt(90+x/2,60,'x')+txt(90+x+a/2,60,s.a);return[svg(p),`(x + ${s.a})(x + ${s.b}) = x² + ${s.a+s.b}x + ${s.a*s.b}. At x = ${s.x}, area = ${(s.x+s.a)*(s.x+s.b)}. Model uses nonnegative lengths.`]});
model('powers','Powers, roots & scientific notation',[N('a','Base / radicand',.01,1000000,16,.01),C('p','Power numerator',-5,6,1),C('q','Power denominator',1,6,2)],'Compare a½ and √a. Find perfect squares, then values whose square roots are not whole numbers.',s=>{let v=s.a**(s.p/s.q),e=Math.floor(Math.log10(s.a)),mant=s.a/10**e;return[`<div class="big-math">${fmt(s.a)}<sup>${frac(s.p,s.q)}</sup> = ${fmt(v)}<p style="font-size:18px">Positive-base real powers</p></div>`,`${fmt(s.a)} = ${fmt(mant)} × 10<sup>${e}</sup>. a<sup>p/q</sup> = (qth root of a)<sup>p</sup>. Display rounded to 4 decimal places.`]});
model('variation','Direct & inverse variation',[C('k','Constant k',1,12,4),S('type','Relationship',['Direct','Inverse']),C('x','Test x',1,10,2)],'Double x. Compare how y changes for direct and inverse variation.',s=>{let f=x=>s.type==='Direct'?s.k*x:s.k/x;return[svg(grid()+plot(f)+dot(300+s.x*25,180-f(s.x)*25,7,'#c38b35')),`${s.type==='Direct'?'y = kx':'y = k/x (x ≠ 0)'}. At x = ${s.x}, y = ${fmt(f(s.x))}. ${s.type==='Direct'?'y/x':'xy'} = ${s.k}. Points outside the viewing window are clipped.`]});
model('circlegraph','Circle on the plane',[C('h','Center x',-5,5,1),C('k','Center y',-4,4,1),C('r','Radius',1,5,3,.5)],'Move the center while preserving the radius. How do the equation and the graph change?',s=>[svg(grid()+`<circle cx="${300+s.h*25}" cy="${180-s.k*25}" r="${s.r*25}" fill="#a8d6bc" fill-opacity=".3" stroke="#2b7c5e" stroke-width="3"/>`+dot(300+s.h*25,180-s.k*25)),`(x − (${s.h}))² + (y − (${s.k}))² = ${s.r*s.r}.<br>x² + y² + (${-2*s.h})x + (${-2*s.k})y + (${s.h*s.h+s.k*s.k-s.r*s.r}) = 0.`]);
model('sets','Sets & probability',[C('a','Only in A',0,20,4),C('both','In both A and B',0,20,3),C('b','Only in B',0,20,5),C('neither','In neither set',0,20,2)],'Create mutually exclusive events, then overlapping events. Why do we subtract the intersection when finding the union?',s=>{let n=s.a+s.b+s.both+s.neither,p=`<rect x="40" y="30" width="520" height="290" fill="#f7faf7" stroke="#b7cabe"/><circle cx="240" cy="160" r="100" fill="#82bda2" fill-opacity=".5"/><circle cx="370" cy="160" r="100" fill="#d9b262" fill-opacity=".5"/>`+txt(190,70,'A')+txt(420,70,'B')+txt(205,165,s.a,28)+txt(305,165,s.both,28)+txt(410,165,s.b,28)+txt(490,295,s.neither,22);return[svg(p),n?`N = ${n}; A ∪ B = ${s.a+s.b+s.both}; A ∩ B = ${s.both}.<br>P(A) = ${fmt((s.a+s.both)/n)}; P(A ∪ B) = ${fmt((s.a+s.b+s.both)/n)}; P(not A) = ${fmt((s.b+s.neither)/n)}; P(A | B) = ${s.b+s.both?fmt(s.both/(s.b+s.both)):'undefined (B is empty)'}.`:'Empty sample space: probabilities are undefined.']});
model('probability','Probability experiments',[C('red','Green tokens',0,20,3),C('gold','Gold tokens',0,20,7),S('replace','Sampling',['With replacement','Without replacement']),B('draw','Draw one token'),B('hundred','Run 100 trials')],'Predict the chance of drawing green. Compare 10 trials with 100 trials. Must experimental probability equal theoretical probability?',s=>{let init=s.red+s.gold;let r=s.replace==='Without replacement'?s.red-(s.greenHits||0):s.red,g=s.replace==='Without replacement'?s.gold-((s.trials||0)-(s.greenHits||0)):s.gold;pcheck: {if(r<0||g<0){s.trials=0;s.greenHits=0;r=s.red;g=s.gold}}let p='';for(let i=0;i<r+g;i++)p+=dot(70+i%10*50,60+Math.floor(i/10)*55,16,i<r?'#3f9a75':'#d4aa58');return[svg(p+txt(300,325,`${s.trials||0} draws • ${s.greenHits||0} green outcomes`,20)),`Next-draw P(green) = ${r+g?fmt(r/(r+g)):'undefined (bag empty)'}. Initial probability = ${init?fmt(s.red/init):'undefined'}. Experimental proportion = ${s.trials?fmt(s.greenHits/s.trials):'no trials yet'}. ${s.replace==='Without replacement'?'The bag empties; reset to refill.':''}`]});
model('counting','Outcome combinations',[C('a','First choice: outcomes',1,6,3),C('b','Second choice: outcomes',1,6,2)],'List all outfits with 3 shirts and 2 pairs of shorts. What changes when another shirt is added?',s=>{let p='';for(let a=0;a<s.a;a++)for(let b=0;b<s.b;b++)p+=rect(80+a*75,35+b*48,68,40,(a+b)%2?'#e5c68d':'#b0d4bd')+txt(114+a*75,62+b*48,`${a+1},${b+1}`,16);return[svg(p),`${s.a} × ${s.b} = ${s.a*s.b} ordered outcomes. If each choice is independent and equally likely, each pair has probability 1/${s.a*s.b}.`]});
model('data','Data & statistics',[T('data','Series A (comma-separated)','3,5,5,7,10'),T('other','Series B (comma-separated)','4,3,6,9,8'),S('view','Display',['Bar graph','Line graph','Double bar graph','Double line graph','Pie graph','Pictograph','Box plot'])],'Change one value to an outlier. Which changes more: the mean or median? Explain what the graph makes visible.',s=>{let parse=v=>String(v).split(',').map(x=>x.trim()).filter(Boolean).map(Number).filter(Number.isFinite).slice(0,30),a=parse(s.data),b=parse(s.other);if(!a.length)return['Enter at least one valid numeric value.','Use comma-separated numbers.'];let sorted=[...a].sort((a,b)=>a-b),sum=a.reduce((x,y)=>x+y,0),mean=sum/a.length,quant=q=>{let pos=(sorted.length-1)*q,i=Math.floor(pos);return sorted[i]+(sorted[Math.min(i+1,sorted.length-1)]-sorted[i])*(pos-i)},median=quant(.5),q1=quant(.25),q3=quant(.75),sd=Math.sqrt(a.reduce((t,v)=>t+(v-mean)**2,0)/a.length),min=Math.min(0,...a,...(s.view.startsWith('Double')?b:[])),max=Math.max(1,...a,...(s.view.startsWith('Double')?b:[])),Y=v=>290-(v-min)/(max-min)*230,p='';if(s.view==='Pie graph'){if(a.some(x=>x<0)||sum<=0)return['Pie charts need nonnegative values with a positive total.','Change the data to counts or positive amounts.'];let angle=-Math.PI/2;let colors=['#419575','#ddb568','#9aa9ca','#7bbeb4','#bd8f77'];a.forEach((v,i)=>{let next=angle+v/sum*2*Math.PI,x=300+120*Math.cos(angle),y=170+120*Math.sin(angle),u=300+120*Math.cos(next),w=170+120*Math.sin(next);p+=v===sum?`<circle cx="300" cy="170" r="120" fill="${colors[i%5]}"/>`:`<path d="M300 170 L${x} ${y} A120 120 0 ${next-angle>Math.PI?1:0} 1 ${u} ${w} Z" fill="${colors[i%5]}" stroke="white"/>`;angle=next});p+=txt(300,330,'Shares: '+a.map(v=>fmt(v/sum*100)+'%').join(' • '),14)}else if(s.view==='Box plot'){let lo=sorted[0],hi=sorted.at(-1),X=v=>70+(v-lo)/(hi-lo||1)*460;p=line(X(lo),170,X(hi),170)+rect(X(q1),120,Math.max(2,X(q3)-X(q1)),100)+line(X(median),120,X(median),220,'#286950',4);[lo,q1,median,q3,hi].forEach((v,i)=>p+=txt(X(v),255+(i%2)*25,fmt(v),15));p+=txt(300,50,'Min • Q1 • Median • Q3 • Max',21)}else if(s.view==='Pictograph'){if(a.some(v=>v<0||!Number.isInteger(v)||v>50))return['Use whole-number counts between 0 and 50 for a pictograph.','One dot represents one observation.'];a.slice(0,8).forEach((v,i)=>{p+=txt(40,40+i*38,i+1,15);for(let j=0;j<v;j++)p+=dot(70+j*9,35+i*38,3.5)});p+=txt(300,355,'One dot = 1. First 8 categories shown.',13)}else{p=line(55,Y(0),550,Y(0));for(let i=0;i<=4;i++){let v=min+(max-min)*i/4;p+=txt(30,Y(v)+5,fmt(v),12)+line(55,Y(v),550,Y(v),'#e3ebe5',1)}let series=s.view.startsWith('Double')?[a,b]:[a],len=Math.max(...series.map(x=>x.length));series.forEach((values,k)=>{let pts=[];values.forEach((v,i)=>{let x=65+i*480/len;if(s.view.includes('line')||s.view.includes('Line')){pts.push([x+15,Y(v)]);p+=dot(x+15,Y(v),4,k?'#c79242':'#3e8f6f')}else p+=rect(x+k*180/len,Math.min(Y(0),Y(v)),170/len,Math.abs(Y(v)-Y(0)),k?'#d5aa58':'#579e80');if(k===0)p+=txt(x+10,320,i+1,12)});if(pts.length)p+=`<polyline points="${pts.map(x=>x.join(',')).join(' ')}" fill="none" stroke="${k?'#c79242':'#3e8f6f'}" stroke-width="3"/>`});p+=txt(300,350,'Category / time index • Green: A • Gold: B',13)}let counts={};a.forEach(v=>counts[v]=(counts[v]||0)+1);let highest=Math.max(...Object.values(counts)),modes=Object.keys(counts).filter(k=>counts[k]===highest);return[svg(p),`Series A: n = ${a.length}; mean = ${fmt(mean)}; median = ${fmt(median)}; mode = ${highest===1?'none':modes.join(', ')}; range = ${fmt(sorted.at(-1)-sorted[0])}; population SD ≈ ${fmt(sd)}.<br>Q1 = ${fmt(q1)}, Q3 = ${fmt(q3)}, IQR = ${fmt(q3-q1)}. Quartiles use linear interpolation; other textbook conventions may differ.`]});
model('interest','Growth & financial mathematics',[N('p','Principal / purchase cost (₱)',0,1000000,10000),C('r','Annual rate (%)',0,30,5,.5),C('t','Years',1,20,5),S('n','Compounds per year',['1','4','12']),S('mode','Model',['Simple interest','Compound interest','Depreciation'])],'Compare simple and compound interest with the same principal, rate, and time. Why does the difference grow?',s=>{let f=t=>s.mode==='Simple interest'?s.p*(1+s.r/100*t):s.mode==='Depreciation'?s.p*(1-s.r/100)**t:s.p*(1+s.r/100/+s.n)**(+s.n*t),end=f(s.t),max=Math.max(1,s.p,end),p=line(60,300,550,300)+line(60,40,60,300),points=[];for(let i=0;i<=s.t;i++){let x=60+i/s.t*480,y=300-f(i)/max*240;points.push([x,y]);p+=dot(x,y,4)+txt(x,330,i,12)}p+=`<polyline points="${points.map(x=>x.join(',')).join(' ')}" fill="none" stroke="#3c9875" stroke-width="3"/>`+txt(300,22,'Amount over time • years on horizontal axis',16);return[svg(p),`${s.mode}: final amount ₱${fmt(end)}; ${s.mode==='Depreciation'?'loss':'interest earned'} ₱${fmt(Math.abs(end-s.p))}. Illustrative fixed-rate mathematics; no fees or taxes.`]});
model('expression','Order of operations',[C('a','a',-10,20,8),C('b','b',-10,20,4),C('c','c',-10,20,3),S('group','Expression',['a + b × c','(a + b) × c','a² + b × c','(a + b) ÷ c'])],'Compare a + b × c and (a + b) × c. Explain which operation comes first and why the answers differ.',s=>{let r=s.group==='a + b × c'?s.a+s.b*s.c:s.group==='(a + b) × c'?(s.a+s.b)*s.c:s.group==='a² + b × c'?s.a**2+s.b*s.c:s.c?(s.a+s.b)/s.c:NaN;return[`<div class="big-math">${esc(s.group)}<p style="font-size:21px">a = ${s.a} • b = ${s.b} • c = ${s.c}</p><b>= ${fmt(r)}</b></div>`,'Grouping first, then exponents, then multiplication and division from left to right, then addition and subtraction from left to right.']});
model('polygon','Polygon angle lab',[C('n','Number of sides',3,12,6),C('turn','Orientation',0,90,0),S('type','Polygon',['Regular','Irregular','Concave'])],'Compare a pentagon and hexagon. How does the interior angle sum change when one side is added?',s=>{let pts=Array.from({length:s.n},(_,i)=>{let a=i*2*Math.PI/s.n-Math.PI/2+s.turn*Math.PI/180,r=s.type==='Concave'&&i===1?30:s.type==='Irregular'&&i===1?90:125;return[300+r*Math.cos(a),175+r*Math.sin(a)]});return[svg(poly(pts)+pts.map((p,i)=>txt(p[0],p[1]-10,String.fromCharCode(65+i),14)).join('')),`${s.n} sides. Interior angle sum = (${s.n} − 2) × 180° = ${(s.n-2)*180}°. ${s.type==='Regular'?'Each interior angle = '+fmt((s.n-2)*180/s.n)+'°; exterior angle = '+fmt(360/s.n)+'°.':'Individual interior angles need not be equal.'}`]});
model('budget','Budget, value & percentages',[N('income','Income / original price (₱)',0,1000000,1000),N('needs','Needs / cost (₱)',0,1000000,600),N('wants','Wants / extra cost (₱)',0,1000000,150),C('rate','Percentage adjustment',-100,100,-10)],'Make a budget that saves at least 20% of income. How does reducing one expense affect your savings?',s=>{let saving=s.income-s.needs-s.wants,max=Math.max(1,s.income,s.needs,s.wants,Math.abs(saving)),vals=[s.income,s.needs,s.wants,Math.max(0,saving)],names=['Income','Needs','Wants','Savings'];return[svg(vals.map((v,i)=>rect(70+i*125,290-v/max*220,75,v/max*220,i===3?'#d2a64e':'#8cbea4')+txt(107+i*125,325,names[i],15)+txt(107+i*125,275-v/max*220,fmt(v),14)).join('')),`Balance = ₱${fmt(saving)}${saving<0?' (budget deficit)':''}. Savings rate = ${s.income?fmt(saving/s.income*100)+'%':'undefined'}.<br>Original ₱${fmt(s.income)} adjusted by ${s.rate}% = ₱${fmt(s.income*(1+s.rate/100))}.`]});
model('rate','Rates & best buys',[N('a','Quantity / distance',.01,10000,120,.01),N('b','Cost / time',.01,10000,3,.01),N('c','Second quantity',.01,10000,200,.01),N('d','Second cost',.01,10000,4,.01)],'Compare two packages by cost per unit. Why can the cheaper package have the higher unit cost?',s=>[svg(rect(80,120,440*s.a/Math.max(s.a,s.c),55,'#9bc9b0')+rect(80,220,440*s.c/Math.max(s.a,s.c),55,'#dfbe7e')+txt(300,80,'Compare quantities using equal units',22)),`Rate A = quantity / time = ${fmt(s.a/s.b)} units per time unit.<br>For shopping: unit cost A = ₱${fmt(s.b/s.a)}; B = ₱${fmt(s.d/s.c)}. ${s.b/s.a<s.d/s.c?'A is better value.':s.b/s.a>s.d/s.c?'B is better value.':'Equal unit costs.'}`]);
model('geometry','Geometry reasoning lab',[S('shape','Relationship',['Parallelogram diagonals','Triangle midline','Perpendicular bisector','Triangle congruence']),C('base','Base',2,12,8),C('height','Height',2,8,5),C('shift','Horizontal shift',-3,3,2)],'Change the shape and record what stays true. State a conjecture, then justify it using definitions or a theorem.',s=>{let x=100,y=290,w=s.base*28,h=s.height*26,d=s.shift*18,A=[x,y],Bv=[x+w,y],D=[x+d,y-h],Cpt=[x+w+d,y-h],mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2],p='',r='';if(s.shape==='Parallelogram diagonals'){p=poly([A,Bv,Cpt,D])+line(...A,...Cpt,'#bd8f41',3)+line(...Bv,...D,'#548a71',3)+dot(...mid(A,Cpt));r='Both diagonals share the same midpoint: each bisects the other. Opposite sides are parallel. Use alternate interior angles and SAS to prove the resulting triangles congruent.'}else if(s.shape==='Triangle midline'){let E=mid(A,D),F=mid(Bv,D);p=poly([A,Bv,D])+line(...E,...F,'#b98738',5);r=`Segment joining two side midpoints is parallel to the base and has length ${s.base/2}, half of ${s.base}. Justify using triangle similarity.`}else if(s.shape==='Perpendicular bisector'){let P=[x+w/2,y-h],midB=mid(A,Bv);p=line(...A,...Bv)+line(midB[0],40,midB[0],320,'#ca9c4f',3)+line(...P,...A)+line(...P,...Bv)+dot(...P);r=`A point on the perpendicular bisector is equidistant from both endpoints. Each distance = √((${s.base}/2)² + ${s.height}²) ≈ ${fmt(Math.hypot(s.base/2,s.height))}. Use SAS with the two right angles.`}else{p=poly([A,Bv,D])+poly([A,Bv,D].map(([x,y])=>[600-x,y-40]),'#dfbd7e');r='The second triangle is a reflected and translated copy: corresponding sides and angles are equal. Congruence can be established by SSS, SAS, or ASA; AAA establishes similarity, not congruence.'}return[svg(p),r]});
model('rational','Rational expressions',[C('a','Factor a',-6,6,2),C('b','Factor b',-6,6,3),C('x','Evaluate at x',-10,10,4,.5)],'Simplify (x² − a²)/(x − a). Why must x = a remain excluded even after cancellation?',s=>{let num=s.x*s.x-s.a*s.a,den=s.x-s.a,p=grid()+plot(x=>x+s.a),holeX=300+s.a*25,holeY=180-2*s.a*25;p+=`<circle cx="${holeX}" cy="${holeY}" r="6" fill="white" stroke="#b3843d" stroke-width="3"/>`;return[svg(p),`(x² − ${s.a*s.a}) / (x − (${s.a})) = x + (${s.a}), with x ≠ ${s.a}.<br>At x = ${s.x}: ${den?fmt(num/den):'undefined — excluded input'}. Also (x + a)(x + b) = x² + (${s.a+s.b})x + (${s.a*s.b}).`]});
model('chords','Intersecting chords',[C('a','First segment of chord 1',1,12,3),C('b','Second segment of chord 1',1,12,8),C('c','First segment of chord 2',1,12,4)],'Predict the missing segment using the product relationship. How must it change if its partner doubles?',s=>{let d=s.a*s.b/s.c,p=`<circle cx="300" cy="170" r="130" fill="#f2f6f0" stroke="#608c73"/>`+line(173,195,424,135,'#3b8b6c',3)+line(230,60,390,265,'#bf9546',3)+dot(285,168)+txt(220,205,s.a,20)+txt(365,155,s.b,20)+txt(245,110,s.c,20)+txt(350,240,fmt(d),20);return[svg(p+txt(300,340,'Schematic illustration; segment lengths are not to scale.',13)),`For chords intersecting inside a circle: a × b = c × d. So d = (${s.a} × ${s.b}) / ${s.c} = ${fmt(d)}. For two secants from an external point: external × whole is equal for both secants.`]});
